		var yInset int32 = win32.OSGetSystemMetrics(win32.OSSM_CYDOUBLECLK) / 2
		var x int32 = win32.OSGET_X_LPARAM(lParam)
		var y int32 = win32.OSGET_Y_LPARAM(lParam)
