func (this *Display) FitRectangleBoundsIntoMonitorWithCursor(rect *win32.RECT) *Rectangle {
	var monitorBounds *Rectangle = this.coordinateSystemMapper.GetContainingMonitorBoundsInPixels(this.GetCursorLocation())
	if monitorBounds == (nil) {
		return nil
	}
	var rectWidth int32 = rect.Right - rect.Left
	var rectHeight int32 = rect.Bottom - rect.Top
	if rect.Left < monitorBounds.X {
		rect.Left = monitorBounds.X
	}
	var monitorBoundsRightEnd int32 = monitorBounds.X + monitorBounds.Width
	if rect.Right > monitorBoundsRightEnd {
		if rectWidth <= monitorBounds.Width {
			rect.Left = monitorBoundsRightEnd - rectWidth
		} else {
			rect.Left = monitorBounds.X
		}
		rectWidth = monitorBoundsRightEnd - rect.Left
	}
	return NewRectangle(rect.Left, rect.Top, rectWidth, rectHeight)
}

